  const offer=appliedReceiptOffer(data,row.receipt,offers.filter(p=>['fixed','percent'].includes(p.discountType))),key=offer?'offer:'+offer.service+':'+(accountOfferKey(offer)||offer.offerId||offer.id):'unmatched';
